// Days to the dates that matter. The next one is drawn big, inside a ring
// that fills as the wait goes by (since last year's, for a date that comes
// every year); the ones after it are listed beside it. On the day itself
// there is confetti.
import { WEEKDAYS, MONTHS } from './time'

const LOOKS: Record<string, { back: string; ink: string; soft: string; line: string; track: string; accents: string[] }> = {
  paper: { back: '#f4efe8', ink: '#2a2420', soft: '#7d7268', line: '#ddd3c6', track: '#e6ddd1', accents: ['#c0533a', '#2f7d74', '#d19a2e', '#5a5fa8', '#a2457b', '#4f7f3a'] },
  night: { back: '#141824', ink: '#f1ece4', soft: '#9aa1b5', line: '#2a3042', track: '#252b3c', accents: ['#f2a65a', '#5ec4b6', '#f2d16b', '#9aa3ff', '#ef8fc4', '#9ed36a'] },
}
// Black ink on white where the panel shows no color: the track a thin ring
// under the thick arc, no tint anywhere. On color e-paper the same looks in
// solid inks, where a cream page or a pastel dithers to confetti.
const HIGH = { back: '#ffffff', ink: '#000000', soft: '#000000', line: '#000000', track: '#000000', accents: ['#000000'], thin: true }
const INKS = {
  paper: { back: '#ffffff', ink: '#000000', soft: '#000000', line: '#000000', track: '#ffff00', accents: ['#ff0000', '#0000ff', '#008000', '#000000'] },
  night: { back: '#000000', ink: '#ffffff', soft: '#ffffff', line: '#ffffff', track: '#0000ff', accents: ['#ffff00', '#ff0000', '#ffffff'] },
}

function lookOf(app: FrameOSApp) {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return HIGH
  const theme = app.config.theme === 'night' ? 'night' : 'paper'
  if (mode === 'auto' && app.frame.paper === true) return INKS[theme]
  return LOOKS[theme]
}

type Event = { name: string; next: number; previous: number | null; days: number; yearly: boolean }

const DAY = 86400000

function localMidnight(year: number, month: number, day: number) {
  return new Date(year, month, day).getTime()
}

// "2026-12-25 Name" once, "12-25 Name" every year.
function parseEvents(text: string, today: number): Event[] {
  const now = new Date(today)
  const events: Event[] = []
  for (const raw of String(text || '').split('\n')) {
    const line = raw.trim()
    const once = line.match(/^(\d{4})-(\d{1,2})-(\d{1,2})\s+(.+)$/)
    const yearly = line.match(/^(\d{1,2})-(\d{1,2})\s+(.+)$/)
    if (once) {
      const next = localMidnight(Number(once[1]), Number(once[2]) - 1, Number(once[3]))
      if (next < today) continue
      events.push({ name: once[4], next, previous: null, days: Math.round((next - today) / DAY), yearly: false })
    } else if (yearly) {
      const month = Number(yearly[1]) - 1
      const day = Number(yearly[2])
      let next = localMidnight(now.getFullYear(), month, day)
      if (next < today) next = localMidnight(now.getFullYear() + 1, month, day)
      const previous = localMidnight(new Date(next).getFullYear() - 1, month, day)
      events.push({ name: yearly[3], next, previous, days: Math.round((next - today) / DAY), yearly: true })
    }
  }
  return events.sort((a, b) => a.days - b.days)
}

function dateText(ms: number, short = false) {
  const d = new Date(ms)
  if (short) return `${WEEKDAYS[d.getDay()].slice(0, 3)} ${d.getDate()} ${MONTHS[d.getMonth()].slice(0, 3)}`
  return `${WEEKDAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()]}`
}

// About how wide a text is: PT Sans (or the face standing in for it) sets
// about half an em a letter.
const widthOf = (text: string, size: number) => text.length * size * 0.5

function arc(cx: number, cy: number, r: number, turns: number) {
  const t = Math.min(0.9999, Math.max(0.0001, turns))
  const a = t * Math.PI * 2
  const x = cx + Math.sin(a) * r
  const y = cy - Math.cos(a) * r
  return `M${cx.toFixed(1)} ${(cy - r).toFixed(1)} A${r.toFixed(1)} ${r.toFixed(1)} 0 ${t > 0.5 ? 1 : 0} 1 ${x.toFixed(1)} ${y.toFixed(1)}`
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const look = lookOf(app)
  const nowDate = new Date()
  const today = localMidnight(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate())
  // Draw again just after midnight, when every count goes down by one.
  const tomorrow = localMidnight(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate() + 1)
  frameos.setNextSleep(Math.min(3600, Math.max(5, (tomorrow - nowDate.getTime()) / 1000 + 5)))

  const events = parseEvents(app.config.events, today)
  if (!events.length) {
    throw new Error('Add a date: "12-25 Christmas"')
  }
  const main = events[0]
  const color = (i: number) => look.accents[i % look.accents.length]
  // The list goes under the ring on a tall or square screen, beside it on a wide one.
  const portrait = H > W * 0.9
  const u = Math.min(W, H) / 100

  // The ring: how far through the wait we are.
  const span = main.previous != null ? main.next - main.previous : 100 * DAY
  const progress = main.days === 0 ? 1 : Math.max(0.02, Math.min(1, 1 - (main.next - today) / span))
  // A round panel: the ring runs along the rim, 12 px in, and the next two
  // dates go in the bottom of the circle, under the count.
  const round = context.round === true
  const ringSize = portrait ? Math.min(W * 0.8, H * 0.42) : Math.min(H * 0.82, W * 0.45)
  const ringWidth = round ? u * 3 : u * 2.2
  const cx = round ? W / 2 : portrait ? W / 2 : u * 6 + ringSize / 2
  const cy = round ? H / 2 : portrait ? u * 6 + ringSize / 2 : H / 2
  const r = round ? Math.min(W, H) / 2 - 12 - ringWidth / 2 : ringSize / 2 - u * 2
  // Where the count's text is laid out: in the ring, or above the list on a round panel.
  const rt = round ? r * 0.8 : r
  const cyT = round ? cy - r * 0.13 : cy

  const bigText = main.days === 0 ? 'Today' : String(main.days)
  // The number sits in the band between the caption and the name, sized so
  // it fits whatever face draws it: Cormorant's old-style figures dip below
  // the line, the fallback face's lining figures stand a full cap height
  // tall (a frame without the font, the store's preview).
  const captionY = cyT - rt * 0.5
  const titleSize = rt * 0.2
  const nameY = cyT + rt * 0.58
  const bandTop = captionY + rt * 0.07
  const bandBottom = nameY - titleSize * 0.78 - rt * 0.05
  const ascent = 0.74
  const descent = 0.36
  const widthLimit = (rt * 1.6) / (bigText.length * 0.58)
  const bigSize = Math.min((bandBottom - bandTop) / (ascent + descent), widthLimit)
  const bigY = bandTop + bigSize * ascent + ((bandBottom - bandTop) - bigSize * (ascent + descent)) / 2
  const caption = main.days === 0 ? 'it is' : main.days === 1 ? 'day until' : 'days until'
  // The date under the name, never under 10 px, short where the ring is narrow there.
  const mainDateSize = round ? Math.max(14, rt * 0.085) : Math.max(10, r * 0.085)
  const mainDate = widthOf(dateText(main.next), mainDateSize) > rt * 1.25 ? dateText(main.next, true) : dateText(main.next)

  // Confetti on the day.
  const confetti = []
  if (main.days === 0) {
    let seed = 7
    const random = () => {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0
      return seed / 4294967296
    }
    for (let i = 0; i < 110; i++) {
      const a = random() * Math.PI * 2
      const d = round ? r * (0.9 - random() * random() * 0.1) : r * (1.08 + random() * random() * 0.45)
      const s = u * (1 + random() * 1.4)
      confetti.push(<rect x={cx + Math.cos(a) * d - s / 2} y={cy + Math.sin(a) * d - s / 4} width={s} height={s / 2} rx={s / 6} fill={color(i)} transform={`rotate(${Math.round(random() * 180)} ${(cx + Math.cos(a) * d).toFixed(1)} ${(cy + Math.sin(a) * d).toFixed(1)})`} />)
    }
  }

  // The rest, beside the ring or under it.
  const listX = portrait ? u * 7 : cx + ringSize / 2 + u * 6
  const listW = W - listX - u * 6
  const listTop = portrait ? cy + ringSize / 2 + u * 6 : u * 9
  // Fewer dates rather than names too small to read.
  const listRoom = H - listTop - u * 6
  let shown = Math.min(5, events.length - 1)
  let slots = Math.max(4, shown + 0.6)
  while (shown > 2 && Math.min(u * 15, listRoom / slots) * 0.36 < 12) {
    shown--
    slots = shown + 0.6
  }
  const rest = round ? [] : events.slice(1, 1 + shown)
  const next = round ? events.slice(1, 3) : []
  const nextSize = Math.max(15, rt * 0.085)
  const rowH = Math.min(u * 15, listRoom / slots)
  const nameSize = Math.min(rowH * 0.36, u * 5)
  const dateSize = Math.max(10, nameSize * 0.55)
  const countOf = (event: Event) => (event.days === 1 ? 'tomorrow' : `${event.days} days`)
  // Each name and its count share a line where every one fits at its size;
  // else (one line split and one not would look uneven) every name has its
  // line to itself and the counts go on the second, beside the dates.
  const textX = listX + u * 4.5
  const together = rest.every((event) => widthOf(event.name, nameSize) + countOf(event).length * nameSize * 1.05 * 0.55 + u * 2.5 <= listX + listW - textX)
  const countSize = together ? nameSize * 1.05 : Math.max(dateSize, nameSize * 0.85)
  // The dates written out where every one fits, else every one short ("Sun 14 Feb").
  const short = rest.some((event) => widthOf(dateText(event.next), dateSize) > listX + listW - textX - (together ? 0 : countOf(event).length * countSize * 0.55 + u * 2))
  // Room for a name at about half an em a letter: Cormorant sets narrower,
  // the fallback face about that wide.
  const fit = (text: string, size: number, width: number) => Math.min(size, width / (text.length * 0.5))

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <rect width={W} height={H} fill={look.back} />
      {confetti}
      <circle cx={cx} cy={cy} r={r} fill="none" stroke={look.track} strokeWidth={look.thin ? Math.max(1, ringWidth * 0.2) : ringWidth} />
      <path d={arc(cx, cy, r, progress)} fill="none" stroke={color(0)} strokeWidth={ringWidth} strokeLinecap="round" />
      <text x={cx} y={captionY} fontFamily="PT Sans" fontSize={round ? Math.max(14, rt * 0.11) : Math.max(10, r * 0.11)} fill={look.soft} textAnchor="middle">
        {caption.toUpperCase()}
      </text>
      <text x={cx} y={bigY} fontFamily="Cormorant Garamond" fontWeight={700} fontSize={bigSize} fill={look.ink} textAnchor="middle">
        {bigText}
      </text>
      <text x={cx} y={nameY} fontFamily="Cormorant Garamond" fontWeight={700} fontSize={fit(main.name, titleSize, rt * 1.5)} fill={color(0)} textAnchor="middle">
        {main.name}
      </text>
      <text x={cx} y={nameY + Math.max(rt * 0.17, mainDateSize * 1.1)} fontFamily="PT Sans" fontSize={mainDateSize} fill={look.soft} textAnchor="middle">
        {mainDate}
      </text>
      {next.map((event, i) => {
        const y = cy + r * (0.6 + i * 0.15)
        const count = event.days === 1 ? 'tomorrow' : `${event.days} days`
        // The name ends left of the dot, the count starts right of it, each
        // in its half of the circle's width there.
        const dy = y - cy + nextSize * 0.3
        const chord = 2 * Math.sqrt(Math.max(0, r * r - dy * dy)) - nextSize * 2
        // The pair (name, dot, count) centred, as big as fits the circle
        // there (12 px at the least); else the dot in the middle and the name
        // cut to its half.
        const ems = event.name.length * 0.5 + count.length * 1.1 * 0.5 + 1.4
        const size = Math.max(12, Math.min(nextSize, chord / ems))
        const nameW = widthOf(event.name, size)
        const countW = count.length * size * 1.1 * 0.5
        const whole = size * ems <= chord
        const dotX = whole ? cx - (size * ems) / 2 + nameW + size * 0.7 : cx
        const half = chord / 2 - size * 0.4
        const name = whole || nameW <= half ? event.name : event.name.slice(0, Math.max(1, Math.floor(half / (size * 0.5)) - 1)) + '…'
        return (
          <g>
            <text x={dotX - size * 0.7} y={y} fontFamily="PT Sans" fontSize={size} fill={look.soft} textAnchor="end">
              {name}
            </text>
            <circle cx={dotX} cy={y - size * 0.32} r={size * 0.26} fill={color(i + 1)} />
            <text x={dotX + size * 0.7} y={y} fontFamily="Cormorant Garamond" fontWeight={700} fontSize={size * 1.1} fill={color(i + 1)}>
              {count}
            </text>
          </g>
        )
      })}

      {rest.length ? (
        <text x={listX} y={listTop - u * 2} fontFamily="PT Sans" fontSize={Math.max(10, u * 3)} fill={look.soft}>
          COMING UP
        </text>
      ) : null}
      {rest.map((event, i) => {
        const y = listTop + i * rowH
        const count = event.days === 1 ? 'tomorrow' : `${event.days} days`
        // The name and the count share the first line where both fit at
        // their size; else the name has the line to itself and the count
        // goes on the second, beside the date.
        const dateY = y + rowH * 0.5 + Math.max(nameSize * 0.85, dateSize * 1.2)
        const date = dateText(event.next, short)
        return (
          <g>
            <line x1={listX} y1={y} x2={listX + listW} y2={y} stroke={look.line} strokeWidth={Math.max(1, u * 0.25)} />
            <circle cx={listX + u * 1.4} cy={y + rowH * 0.42} r={u * 1.2} fill={color(i + 1)} />
            <text x={textX} y={y + rowH * 0.5} fontFamily="Cormorant Garamond" fontWeight={700} fontSize={fit(event.name, nameSize, listX + listW - textX)} fill={look.ink}>
              {event.name}
            </text>
            <text x={textX} y={dateY} fontFamily="PT Sans" fontSize={dateSize} fill={look.soft}>
              {date}
            </text>
            <text x={listX + listW} y={together ? y + rowH * 0.5 : dateY} fontFamily="Cormorant Garamond" fontWeight={700} fontSize={countSize} fill={color(i + 1)} textAnchor="end">
              {count}
            </text>
          </g>
        )
      })}
    </svg>
  )
}

